if.script:
const ref = refOut.pageReference
if (ref != null && ref.exists && ref.supportsVersion()) {
    let version = null
    try { version = ref.getVersion(String(publishedVersionName)) } catch (e) { version = null }
    if (version == null) ec.message.addError(ec.resource.expand('This page has no version ${name}', '', {name: String(publishedVersionName)}))
    else publishedVersionName = version.versionName
}

actions.script:
pageReference = null
pageLocation = null
exists = false
let root = rootPageLocation
if (!root && wikiSpaceId) root = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId)
        .useCache(true).disableAuthz().one()?.rootPageLocation
if (!root) { ec.message.addError(ec.l10n.localize('This space has no place for its pages (no root page location)')); return }
const parts = String(pagePath || '').split('/').filter((part) => part !== '')
if (parts.some((part) => part === '.' || part === '..')) { ec.message.addError(ec.l10n.localize('A page path has no . or .. in it')); return }
const rootRef = ec.resource.getLocationReference(String(root))
if (!parts.length) {
    pageReference = rootRef
} else {
    // the root page's directory: its location without one extension at a time, the first that is a directory,
    // else without them all (only the file name's; not findMatchingDirectory, which goes on into the path)
    const rootLocation = String(root)
    const slash = rootLocation.lastIndexOf('/')
    let rootDir = rootLocation
    let candidate = rootLocation
    while (candidate.lastIndexOf('.') > slash) {
        candidate = candidate.substring(0, candidate.lastIndexOf('.'))
        rootDir = candidate
        const candidateRef = ec.resource.getLocationReference(candidate)
        if (candidateRef.exists && candidateRef.isDirectory()) break
    }
    const name = parts.pop()
    const dirLocation = [rootDir.replace(/\/+$/, '')].concat(parts).join('/')
    const dir = ec.resource.getLocationReference(dirLocation)
    let found = null
    // the usual names first, then the directory's files
    for (const fileName of [name, `${name}.md`, `${name}.html`]) {
        const direct = ec.resource.getLocationReference(`${dirLocation}/${fileName}`)
        if (direct.exists && direct.isFile()) { found = direct; break }
    }
    if (found == null && dir.exists && dir.isDirectory()) {
        const files = Array.from(dir.getDirectoryEntries()).filter((entry) => entry.isFile())
        found = files.find((entry) => entry.fileName === name) ||
                files.find((entry) => entry.fileName.replace(/\.[^.]*$/, '') === name) || null
    }
    pageReference = found || ec.resource.getLocationReference(`${dirLocation}/${name}${wikiType ? '.' + wikiType : ''}`)
}
pageLocation = pageReference.location
exists = !!pageReference.exists

if (pageText != pageReference.getText()) {
    pageReference.putText(pageText ?? '', versionNote || null)
    if (pageReference.supportsVersion()) versionName = pageReference.getCurrentVersion()?.versionName
    updatedPage = true
}

// each path element form encoded, as java.net.URLEncoder does
const formEncode = (text) => encodeURIComponent(text).replace(/[!'()~]/g,
        (ch) => '%' + ch.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+')
encodedPagePath = (pagePath || '').split('/').map(formEncode).join('/')

service-call.in-map:
{wikiSpaceId:wikiSpaceId, description:description, repositoryKind:repositoryKind, repositoryId:repositoryId,
                            branch:branch, localPath:localPath, remoteUrl:remoteUrl, username:username, accessToken:accessToken,
                            fetchIntervalMinutes:fetchIntervalMinutes}

else.script:
rootPageReference.putText(`
Automatic root page for space ${description || wikiSpaceId}

`)

actions.script:
// the members: the creator with every right, then memberList (view unless it says more)
const members = new Map()
if (addCreator && ec.user.userId) members.set(ec.user.userId, {allowAdmin: 'Y', allowView: 'Y', allowUpdate: 'Y'})
for (const member of Array.from(memberList || [])) {
    if (!member || !member.userId || members.has(member.userId)) continue
    const flag = (value, otherwise) => value == null ? otherwise : (value === true || value === 'Y' ? 'Y' : 'N')
    members.set(member.userId, {allowAdmin: flag(member.allowAdmin, 'N'), allowView: flag(member.allowView, 'Y'),
        allowUpdate: flag(member.allowUpdate, 'N')})
}
for (const [userId, flags] of members) {
    ec.service.sync().name('create#moqui.resource.wiki.WikiSpaceUser').parameters(Object.assign({wikiSpaceId: wikiSpaceId,
        userId: userId, receiveNotifications: 'N'}, flags)).call()
}

const KINDS = ['db', 'local', 'remote']
if (!KINDS.includes(repositoryKind)) { ec.message.addError(`Unknown space storage ${repositoryKind} (db, local or remote)`); return }
const isAdmin = ec.artifactExecution.authzDisabled() || ec.user.isInGroup('ADMIN')
if (repositoryKind === 'remote' && !isAdmin) { ec.message.addError('Only an administrator adds a mirror'); return }
if (repositoryKind === 'remote' && !remoteUrl) { ec.message.addError('A mirror needs the URL to fetch'); return }
const given = !!repositoryId
if (!repositoryId) repositoryId = `WIKI_${wikiSpaceId}`
const existing = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).disableAuthz().one()
if (existing != null) {
    if (!given) { ec.message.addError(`Git repository ${repositoryId} already exists`); return }
    rootPageDirectory = `git://${repositoryId}`
    return
}
const repo = ec.entity.makeValue('moqui.resource.GitRepository')
const remote = repositoryKind === 'remote'
repo.setFields({repositoryId: repositoryId, description: description || `Wiki space ${wikiSpaceId}`,
    repositoryKind: repositoryKind, branch: branch || 'main', localPath: localPath || null,
    remoteUrl: remote ? remoteUrl : null, username: remote ? (username || null) : null,
    accessToken: remote ? (accessToken || null) : null, fetchIntervalMinutes: remote ? (fetchIntervalMinutes ?? 60) : null},
    true, null, null)
repo.create()
rootPageDirectory = `git://${repositoryId}`
if (!remote) {
    ec.service.sync().name('org.moqui.impl.GitServices.init#GitRepository').parameter('repositoryId', repositoryId).call()
    return
}
// the first fetch in its own transaction: a failure (no network, sim mode) is recorded on the repository and
// reported, and the space stays; the fetch job fetches it again
ec.message.pushErrors()
ec.service.sync().name('org.moqui.impl.GitServices.fetch#GitRepository').parameter('repositoryId', repositoryId)
        .requireNewTransaction(true).call()
const fetchError = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.message.popErrors()
if (fetchError) ec.message.addMessage(`The first fetch of ${remoteUrl} failed: ${fetchError}`, 'warning')

// disableAuthz answers true when authorization was disabled already, as for internal work
if (userId !== ec.user.userId && !ec.artifactExecution.disableAuthz()) {
    ec.artifactExecution.enableAuthz()
    ec.message.addError("Another user's notes space is made only with authorization disabled")
}

const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    let wikiSpace = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId).one()
    if (wikiSpace == null) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).one()
        if (account == null) {
            ec.message.addError(`No user ${userId} to make a notes space for`)
        } else {
            const description = 'Notes of ' + (account.userFullName || account.username || userId)
            rootPageLocation = `dbresource://WikiSpace/${wikiSpaceId}.md`
            ec.service.sync().name('create#moqui.resource.wiki.WikiSpace').parameters({wikiSpaceId: wikiSpaceId,
                description: description, rootPageLocation: rootPageLocation, restrictView: 'Y', restrictUpdate: 'Y',
                allowAnyHtml: 'N'}).call()
            // the root page, as create#WikiSpace writes one when no file is there
            const rootPageReference = ec.resource.getLocationReference(rootPageLocation)
            if (!rootPageReference.exists) rootPageReference.putText(`\n# ${description}\n\n`)
            created = true
        }
    } else {
        rootPageLocation = wikiSpace.rootPageLocation
    }
    if (!ec.message.hasError()) {
        const owner = ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition('wikiSpaceId', wikiSpaceId)
                .condition('userId', userId).one()
        if (owner == null) {
            ec.service.sync().name('create#moqui.resource.wiki.WikiSpaceUser').parameters({wikiSpaceId: wikiSpaceId,
                userId: userId, allowAdmin: 'Y', allowView: 'Y', allowUpdate: 'Y', receiveNotifications: 'N'}).call()
        }
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

then.script:
const versionMaps = copyOut.versionMaps || {}
const basePages = Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', baseWikiSpaceId).list())
const newIds = {}
const made = []
// each page's rows with the new version names (copy#WikiPageRows), with its aliases, as the new space has none
for (const basePage of basePages) {
    const out = ec.service.sync().name('org.moqui.impl.WikiServices.copy#WikiPageRows').parameters({baseWikiPageId: basePage.wikiPageId,
        wikiSpaceId: wikiSpaceId, rootPageLocation: rootPageLocation, pagePath: basePage.pagePath || null,
        versionMap: versionMaps[basePage.pagePath || ''] || {}, publishNew: publishNew, copyAliases: true, copyCategories: true}).call()
    if (ec.message.hasError()) return
    newIds[basePage.wikiPageId] = out.wikiPageId
    made.push([basePage, out.wikiPageId])
}
// the parents, by the new ids
for (const [basePage, newId] of made) {
    if (basePage.parentWikiPageId && newIds[basePage.parentWikiPageId]) {
        const page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', newId).one()
        page.parentWikiPageId = newIds[basePage.parentWikiPageId]
        page.update()
    }
}
for (const [, newId] of made) {
    ec.service.sync().name('org.moqui.impl.WikiServices.index#WikiPageLinks').parameter('wikiPageId', newId).call()
}

service-call.in-map:
{sourceLocation:basePageInfo.pageLocation, targetLocation:targetFileOut.pageLocation, withHistory:true, pageOnly:true,
                                originNote:(versionNote ? String(versionNote).trim() : ('Copied from ' + baseWikiSpaceId + '/' + basePageInfo.pagePath)),
                                skipNames:(copyAttachments ? [] : ['_attachments'])}

then.script:
for (const failure of Array.from(copyOut.failureList || [])) {
    const name = failure.path || targetFileOut.pageReference.fileName
    if (!failedFiles.includes(name)) failedFiles.push(name)
}
const parentRows = Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId)
        .condition('pagePath', parentPath || null).list())
parentWikiPageId = parentRows.length ? parentRows[0].wikiPageId : null

iterate.script:
try {
    if (baseAttachOut.attachmentReference == null || attachOut.attachmentReference == null) throw new Error('no place for the file')
    attachOut.attachmentReference.copyFrom(baseAttachOut.attachmentReference)
} catch (e) {
    ec.logger.error(`Attachment ${attachmentInfo.filename} of ${baseWikiSpaceId}/${basePageInfo.pagePath} not copied to ${wikiSpaceId}/${newPageInfo.pagePath}: ${e && e.message ? e.message : e}`)
    failedFiles.push(attachmentInfo.filename)
}

actions.script:
const map = versionMap || {}
const basePage = baseWikiPageId ? ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', baseWikiPageId).one() : null
if (baseWikiPageId && basePage == null) { ec.message.addError(`No page ${baseWikiPageId} to copy`); return }
// the copied file at the page's exact path, not a page of that name elsewhere
const newRef = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageFile')
        .parameters({rootPageLocation: rootPageLocation || null, wikiSpaceId: wikiSpaceId, pagePath: pagePath || ''}).call()?.pageReference
if (ec.message.hasError()) return
const current = newRef?.exists && newRef.supportsVersion() ? (newRef.getCurrentVersion()?.versionName ?? null) : null
const published = basePage?.publishedVersionName ? (map[basePage.publishedVersionName] ?? null) : (publishNew ? current : null)
// a path that was only an alias of a moved page is the new page's
if (pagePath) ec.entity.find('moqui.resource.wiki.WikiPageAlias').condition('wikiSpaceId', wikiSpaceId).condition('aliasPath', pagePath).deleteAll()
const page = ec.entity.makeValue('moqui.resource.wiki.WikiPage')
page.setFields({wikiSpaceId: wikiSpaceId, pagePath: pagePath || null, parentWikiPageId: parentWikiPageId || null,
    sequenceNum: basePage?.sequenceNum ?? null, createdByUserId: (basePage ? basePage.createdByUserId : ec.user.userId) || null,
    publishedVersionName: published, restrictView: basePage?.restrictView || null, restrictUpdate: basePage?.restrictUpdate || null}, true, null, null)
page.setSequencedIdPrimary()
page.create()
wikiPageId = page.wikiPageId
if (basePage == null) return
for (const row of Array.from(ec.entity.find('moqui.resource.wiki.WikiPageHistory').condition('wikiPageId', basePage.wikiPageId).list())) {
    const copy = row.cloneValue()
    copy.wikiPageId = wikiPageId
    if (copy.versionName) copy.versionName = map[copy.versionName] ?? null
    copy.create()
}
const rowEntities = ['moqui.resource.wiki.WikiPageUser'].concat(copyCategories ? ['moqui.resource.wiki.WikiPageCategoryMember'] : [])
for (const entityName of rowEntities) {
    for (const row of Array.from(ec.entity.find(entityName).condition('wikiPageId', basePage.wikiPageId).list())) {
        const copy = row.cloneValue()
        copy.wikiPageId = wikiPageId
        copy.create()
    }
}
if (copyAliases) {
    for (const alias of Array.from(ec.entity.find('moqui.resource.wiki.WikiPageAlias').condition('wikiSpaceId', basePage.wikiSpaceId)
            .condition('wikiPageId', basePage.wikiPageId).list())) {
        if (ec.entity.find('moqui.resource.wiki.WikiPageAlias').condition('wikiSpaceId', wikiSpaceId).condition('aliasPath', alias.aliasPath).one() != null) {
            ec.message.addMessage(`Not copying wiki page alias ${alias.aliasPath}, already exists in space ${wikiSpaceId}`, 'warning')
            continue
        }
        const copy = alias.cloneValue()
        copy.wikiSpaceId = wikiSpaceId
        copy.wikiPageId = wikiPageId
        copy.create()
    }
}

if.script:
// a child page's record (one without a file) keeps no parent that is not there
for (const child of Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('parentWikiPageId', wikiPageId).list())) {
    child.parentWikiPageId = null
    child.update()
}

for (const link of Array.from(ec.entity.find('moqui.resource.wiki.WikiPageLink').condition('toWikiPageId', wikiPageId).list())) {
    link.toWikiPageId = null
    link.update()
}
// its reviews go, and a review still waiting leaves the reviewers' approvals
for (const review of Array.from(ec.entity.find('moqui.resource.wiki.WikiPageReview').condition('wikiPageId', wikiPageId).list())) {
    if (review.notificationMessageId) ec.service.sync().name('org.moqui.impl.WikiServices.close#WikiPageReviewNotification')
            .parameter('notificationMessageId', review.notificationMessageId).call()
    review.delete()
}

try { matchingDirRef.delete() }
catch (t) {
    ec.logger.warn('Could not delete the directory ' + matchingDirRef.location + ' of a deleted wiki page: ' + String(t))
    ec.message.addMessage(ec.l10n.localize('The page was deleted, but the folder of its files was not'), 'danger')
}

// not filterMapList, which removes only an equal path: remove every page under currentPagePath
for (let i = allChildFileFlatList.length - 1; i >= 0; i--)
    if (String(allChildFileFlatList[i].path).startsWith(currentPagePath)) allChildFileFlatList.splice(i, 1)

for (let i = allChildFileFlatList.length - 1; i >= 0; i--) {
    const allChildFileFlat = allChildFileFlatList[i]
    if (!allChildFileFlat) continue
    const resultMap = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageId')
        .parameters({wikiSpaceId:wikiSpaceId, pagePath:allChildFileFlat.path, createIfMissing: false}).call()
    const childPageId = resultMap.wikiPageId
    const inCategory = childPageId && ec.entity.find("moqui.resource.wiki.WikiPageCategoryMember")
            .condition(ec.entity.conditionFactory.makeConditionDate("fromDate", "thruDate", null))
            .condition({wikiPageId:childPageId, wikiPageCategoryId:wikiPageCategoryId}).one() != null
    if (!inCategory) allChildFileFlatList.splice(i, 1)
}

actions.script:
// the page records by path, for the restricted pages and the detail
const pages = new Map()
for (const page of Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId).list()))
    pages.set(page.pagePath || '', page)
const scope = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiViewScope').call()
const hidden = new Set(Array.from(scope.hiddenPageIdList || []))
if (hidden.size) {
    const hiddenPaths = []
    for (const [path, page] of pages) if (hidden.has(page.wikiPageId)) hiddenPaths.push(path)
    const isHidden = (path) => hiddenPaths.some((hiddenPath) => hiddenPath && (path === hiddenPath || String(path).startsWith(hiddenPath + '/')))
    for (let i = allChildFileFlatList.length - 1; i >= 0; i--) if (isHidden(allChildFileFlatList[i].path)) allChildFileFlatList.splice(i, 1)
    const prune = (list) => {
        for (let i = list.length - 1; i >= 0; i--) {
            if (isHidden(list[i].path)) list.splice(i, 1)
            else if (list[i].childResourceList) prune(list[i].childResourceList)
        }
    }
    prune(rootChildResourceList)
}
if (includeDetail) {
    const categoryNames = new Map()
    const nameOf = (categoryId) => {
        if (!categoryNames.has(categoryId)) categoryNames.set(categoryId, ec.entity.find('moqui.resource.wiki.WikiPageCategory')
                .condition('wikiPageCategoryId', categoryId).useCache(true).one()?.categoryName || categoryId)
        return categoryNames.get(categoryId)
    }
    const dateFilter = ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)
    for (const item of allChildFileFlatList) {
        const page = pages.get(item.path || '')
        item.wikiPageId = page?.wikiPageId || null
        let text = ''
        try {
            text = ec.resource.getLocationText(item.location) || ''
            const change = ec.resource.getLastChange(item.location)
            item.modifiedDate = change?.date ?? null
            item.modifiedByUserId = change?.userId ?? null
        } catch (e) {
            ec.logger.warn(`Wiki page ${wikiSpaceId}/${item.path} not read for its detail: ${e}`)
        }
        const heading = text.match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/m)
        item.title = heading ? heading[1] : (item.path ? item.name : (wikiSpace.description || wikiSpaceId))
        const body = heading ? text.slice(text.indexOf(heading[0]) + heading[0].length) : text
        item.snippet = body.replace(/[#>*_`~\[\]()!|-]+/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 200)
        const members = page ? Array.from(ec.entity.find('moqui.resource.wiki.WikiPageCategoryMember')
                .condition('wikiPageId', page.wikiPageId).condition(dateFilter).list()) : []
        item.categoryIdList = members.map((member) => member.wikiPageCategoryId)
        item.categoryNameList = item.categoryIdList.map(nameOf)
        item.pinned = item.categoryIdList.includes('Pinned') || item.categoryNameList.includes('Pinned')
    }
}

const wikiSpace = ec.entity.find("moqui.resource.wiki.WikiSpace").condition("wikiSpaceId", document.wikiSpaceId)
        .useCache(true).one();
if (wikiSpace == null || !wikiSpace.rootPageLocation) return;
let pageLocation = wikiSpace.rootPageLocation;
const segments = document.pagePath ? String(document.pagePath).split("/") : [];
const pageName = segments.length ? segments.pop() : (wikiSpace.description || document.wikiSpaceId);
if (document.pagePath) {
    // the child pages are under a directory named as the root page without its extension
    const directory = [pageLocation.replace(/\.[^/.]*$/, "")].concat(segments).join("/");
    const page = ec.resource.getLocationReference(directory).getDirectoryEntries().find((entry) => entry.isFile() &&
            (entry.getFileName() === pageName || entry.getFileName().replace(/\.[^.]*$/, "") === pageName));
    if (page == null) return;
    pageLocation = page.getLocation();
}
const text = ec.resource.getLocationText(pageLocation);
document.content = text;
document.pageName = pageName;
const heading = String(text || "").match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/m) || String(text || "").match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
document.title = heading ? heading[1].replace(/<[^>]+>/g, "").trim() : pageName;
try {
    const change = ec.resource.getLastChange(pageLocation);
    document.updatedDate = change?.date ?? null;
    document.updatedByUserId = change?.userId ?? null;
} catch (e) {
    ec.logger.warn(`Wiki page ${document.wikiSpaceId}/${document.pagePath || ''} has no last change: ${e}`);
}
if (document.wikiPageId) {
    const row = ec.entity.find("moqui.resource.wiki.WikiPage").condition("wikiPageId", document.wikiPageId).one();
    document.createdByUserId = row?.createdByUserId ?? null;
    document.restrictView = row?.restrictView === "Y" ? "Y" : "N";
}

canView = false
canUpdate = false
canAdmin = false
readOnly = false
storage = null
repositoryId = null
repositoryKind = null
const current = !userId || userId === ec.user.userId
if (!userId) userId = ec.user.userId || null
const authzOff = ec.artifactExecution.authzDisabled()
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    let page = null
    if (wikiPageId) {
        page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', wikiPageId).one()
        if (page == null) return
        wikiSpaceId = page.wikiSpaceId
    }
    if (!wikiSpaceId) return
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId).useCache(true).one()
    if (space == null) return
    const root = String(space.rootPageLocation || '')
    if (root.startsWith('git://')) {
        storage = 'git'
        repositoryId = root.slice(6).split('/')[0]
        const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).one()
        repositoryKind = repo?.repositoryKind || null
        readOnly = repositoryKind === 'remote'
    } else {
        storage = root.startsWith('dbresource://') ? 'db' : 'other'
    }
    if (!userId && authzOff) {
        canView = true
        canUpdate = !readOnly
        canAdmin = true
        return
    }
    const spaceUser = userId ? ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition({wikiSpaceId: wikiSpaceId, userId: userId}).one() : null
    const pageUser = page && userId ? ec.entity.find('moqui.resource.wiki.WikiPageUser').condition({wikiPageId: page.wikiPageId, userId: userId}).one() : null
    const adminGroup = !!userId && (current ? ec.user.isInGroup('ADMIN') : ec.entity.find('moqui.security.UserGroupMember')
            .condition({userGroupId: 'ADMIN', userId: userId})
            .condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)).count() > 0)
    canView = adminGroup || ((space.restrictView !== 'Y' || spaceUser?.allowView === 'Y' || spaceUser?.allowAdmin === 'Y') &&
            (!page || page.restrictView !== 'Y' || pageUser?.allowView === 'Y'))
    canAdmin = spaceUser?.allowAdmin === 'Y' || adminGroup
    // an administrator of the space (who may give themselves update anyway) or the ADMIN group updates what
    // they may view; others through restrictUpdate's rows
    canUpdate = canView && !readOnly && (canAdmin || ((space.restrictUpdate !== 'Y' || spaceUser?.allowUpdate === 'Y') &&
            (!page || page.restrictUpdate !== 'Y' || pageUser?.allowUpdate === 'Y')))
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

viewSpaceIdList = []
hiddenPageIdList = []
const current = !userId || userId === ec.user.userId
if (!userId) userId = ec.user.userId || null
const authzOff = ec.artifactExecution.authzDisabled()
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const spaces = Array.from(ec.entity.find('moqui.resource.wiki.WikiSpace').selectField('wikiSpaceId,restrictView').list())
    const adminGroup = !!userId && (current ? ec.user.isInGroup('ADMIN') : ec.entity.find('moqui.security.UserGroupMember')
            .condition({userGroupId: 'ADMIN', userId: userId})
            .condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)).count() > 0)
    if ((!userId && authzOff) || adminGroup) {
        viewSpaceIdList = spaces.map((space) => space.wikiSpaceId)
        return
    }
    const memberSpaces = new Set(userId ? Array.from(ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition('userId', userId).list())
            .filter((row) => row.allowView === 'Y' || row.allowAdmin === 'Y').map((row) => row.wikiSpaceId) : [])
    viewSpaceIdList = spaces.filter((space) => space.restrictView !== 'Y' || memberSpaces.has(space.wikiSpaceId))
            .map((space) => space.wikiSpaceId)
    const viewPages = new Set(userId ? Array.from(ec.entity.find('moqui.resource.wiki.WikiPageUser')
            .condition({userId: userId, allowView: 'Y'}).list()).map((row) => row.wikiPageId) : [])
    hiddenPageIdList = Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('restrictView', 'Y')
