const fromDirRef = ec.resource.getLocationReference(fromDirLoc)
const toLoc = `${toRootDir}/${toPath}${ext}`
const toDirLoc = `${toRootDir}/${toPath}`
if (pageFileOf(toRootDir, toPath) != null || ec.resource.getLocationReference(toLoc).exists ||
        ec.resource.getLocationReference(toDirLoc).exists) return fail('There is a page named ${name} there already', {name: toPageName})
if (toParentPath && pageFileOf(toRootDir, toParentPath) == null) return fail('Parent page not found')
const under = (spaceId, path) => Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', spaceId)
        .condition('pagePath', 'like', path + '%').list()).filter((row) => row.pagePath === path || String(row.pagePath).startsWith(path + '/'))
