const moved = under(fromSpaceId, fromPath).sort((left, right) => String(left.pagePath).length - String(right.pagePath).length)

// the files: moved on the same storage, else replayed with their history and then removed
const storeOf = (location) => location.startsWith('git://') ? 'git://' + location.slice(6).split('/')[0] : location.split('://')[0]
const note = versionNote ? String(versionNote).trim().substring(0, 255) : null
const moveNote = note || `Move ${fromSpaceId}/${fromPath} to ${toWikiSpaceId}/${toPath}`
