// the rows: the same ids at their new place, the version names of a replay, the move in the history, an alias
const now = ec.user.nowTimestamp
const parentRows = Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', toWikiSpaceId)
