    ec.service.sync().name('org.moqui.impl.WikiServices.resolve#WikiPageLinksTo').parameter('wikiPageId', id).call()
}
wikiPageId = page.wikiPageId
wikiSpaceId = toWikiSpaceId
pagePath = toPath

const formEncode = (text) => encodeURIComponent(text).replace(/[!'()~]/g,
        (ch) => '%' + ch.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+')
