versionMaps = {}
versionCount = 0
fileCount = 0
failureList = []
const skip = new Set(Array.from(skipNames || []).map(String))
const sourceRef = ec.resource.getLocationReference(sourceLocation)
if (!sourceRef.exists || !sourceRef.isFile()) { ec.message.addError(`No page at ${sourceLocation}`); return }
if (ec.resource.getLocationReference(targetLocation).exists) { ec.message.addError(`There is a file at ${targetLocation} already`); return }
const dirOf = (location) => location.replace(/\.[^/.]*$/, '')
const files = [{source: sourceLocation, target: targetLocation, rel: ''}]
const walk = (source, target, base, depth) => {
    const dir = ec.resource.getLocationReference(source)
    if (!dir.exists || !dir.isDirectory() || depth > 32) return
    for (const entry of dir.getDirectoryEntries()) {
        const name = entry.fileName
        if (name === '.gitkeep' || skip.has(name)) continue
        if (pageOnly && depth === 0 && name !== '_attachments') continue
        const rel = base ? `${base}/${name}` : name
