        else files.push({source: entry.location, target: `${target}/${name}`, rel: rel})
    }
}
if (dirOf(sourceLocation) !== sourceLocation) walk(dirOf(sourceLocation), dirOf(targetLocation), '', 0)
fileCount = files.length

// each file's versions, oldest first; a file with none (or no history wanted) once, as it is now
const lists = files.map((file) => {
    let history = []
    try {
        const ref = ec.resource.getLocationReference(file.source)
        if (withHistory && ref.supportsVersion()) history = Array.from(ref.getVersionHistory() || []).reverse()
    } catch (e) {
        ec.logger.warn(`Versions of ${file.source} not read, copying its current text: ${e}`)
    }
