    } catch (e) {
        ec.logger.error(`The current text of ${file.source} not copied to ${file.target}: ${e}`)
    }
}

linkCount = 0
try {
    const page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', wikiPageId).one()
    if (page == null) return
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', page.wikiSpaceId).useCache(true).one()
    if (space == null || !space.rootPageLocation) return
