    const target = link.toWikiPageId ? ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', link.toWikiPageId).one() : null
    const found = target != null && viewSpaces.has(target.wikiSpaceId) && !hidden.has(target.wikiPageId)
    linkList.push({toWikiSpaceId: found ? target.wikiSpaceId : link.toWikiSpaceId, toPagePath: found ? (target.pagePath || '') : (link.toPagePath || ''),
        toWikiPageId: found ? target.wikiPageId : null, linkText: link.linkText, linkTarget: link.linkTarget, found: found})
}

const ref = info.pageReference
wikiPageId = info.wikiPageId
wikiSpaceId = info.wikiSpaceId
pagePath = info.pagePath
currentVersionName = info.currentVersionName
publishedVersionName = info.publishedVersionName
const location = String(info.pageLocation || '')
storage = location.startsWith('git://') ? 'git' : location.startsWith('dbresource://') ? 'db' : 'other'
const users = {}
const userName = (userId) => {
