    if (!(userId in users)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        users[userId] = account ? (account.userFullName || account.username || userId) : userId
    }
    return users[userId]
}
const short = (name) => name == null ? '' : String(name).length > 12 ? String(name).substring(0, 10) : String(name)
const rows = wikiPageId ? Array.from(ec.entity.find('moqui.resource.wiki.WikiPageHistory').condition('wikiPageId', wikiPageId)
        .orderBy('-changeDateTime,-historySeqId').list()) : []
const moves = {}
historyList = rows.map((row) => {
    const movedFrom = row.oldPagePath ? (row.oldWikiSpaceId ? `${row.oldWikiSpaceId}/${row.oldPagePath}` : row.oldPagePath) : null
    if (movedFrom && row.versionName && !(row.versionName in moves)) moves[row.versionName] = movedFrom
    return {historySeqId: row.historySeqId, changeDateTime: row.changeDateTime, userId: row.userId, userName: userName(row.userId),
        versionName: row.versionName, shortName: short(row.versionName), versionNote: row.versionNote, oldPagePath: row.oldPagePath,
        oldWikiSpaceId: row.oldWikiSpaceId, movedFrom: movedFrom}
})
const history = ref?.exists && ref.supportsVersion() ? Array.from(ref.getVersionHistory() || []) : []
versionList = history.map((version, index) => ({versionName: version.versionName, shortName: short(version.versionName),
    previousVersionName: version.previousVersionName, versionDate: version.versionDate, userId: version.userId,
    userName: userName(version.userId), note: version.note, isCurrent: index === 0,
    isPublished: version.versionName === publishedVersionName, movedFrom: moves[version.versionName] || null}))

const ref = info.pageReference
if (!ref?.exists || !ref.supportsVersion()) { ec.message.addError(ec.l10n.localize('This page keeps no versions to compare')); return }
if (!fromVersionName) {
    const to = toVersionName ? ref.getVersion(toVersionName) : ref.getCurrentVersion()
    fromVersionName = to?.previousVersionName || null
    if (!fromVersionName) { ec.message.addError(ec.l10n.localize('There is no earlier version to compare with')); return }
}
try {
