    if (version == null) { ec.message.addError(ec.resource.expand('This page has no version ${name}', '', {name: String(versionName)})); return }
    versionName = version.versionName
}
const nameOf = (userId) => {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
    return account ? (account.userFullName || account.username || userId) : null
}
const reviewers = Array.from(new Set((reviewerUserIdList ? Array.from(reviewerUserIdList) : []).concat([reviewerUserId])
        .filter((id) => id).map(String)))
for (const reviewer of reviewers) {
    const name = nameOf(reviewer)
    if (name == null) { ec.message.addError(ec.resource.expand('No user ${user}', '', {user: reviewer})); return }
    const access = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageAccess').parameters({wikiPageId: pageId, userId: reviewer}).call()
    if (!access.canView) { ec.message.addError(ec.resource.expand('${name} may not view this page', '', {name: name})); return }
}
