const pageName = pagePathText ? pagePathText.slice(pagePathText.lastIndexOf('/') + 1) : (info.wikiSpace?.description || info.wikiSpaceId)
const authorName = nameOf(me) || me
const now = ec.user.nowTimestamp
for (const reviewer of (reviewers.length ? reviewers : [null])) {
