            .condition('reviewerUserId', reviewer).list())
    const review = ec.entity.makeValue('moqui.resource.wiki.WikiPageReview')
    review.setSequencedIdPrimary()
    review.setFields({wikiPageId: pageId, versionName: versionName, baseVersionName: info.publishedVersionName || null,
        statusId: 'WprRequested', requestedByUserId: me, reviewerUserId: reviewer, requestedDate: now, dueDate: dueDate || null,
        note: note || null}, true, null, null)
    review.create()
    wikiPageReviewIdList.push(review.wikiPageReviewId)
    // the reviewer, or for anyone the space's administrators
    let recipients = reviewer ? [reviewer] : Array.from(ec.entity.find('moqui.resource.wiki.WikiSpaceUser')
            .condition({wikiSpaceId: info.wikiSpaceId, allowAdmin: 'Y'}).list()).map((row) => row.userId)
    recipients = recipients.filter((id) => id && id !== me)
    if (recipients.length) {
        try {
            const nm = ec.makeNotificationMessage().topic('WikiPageReview').message({wikiPageReviewId: review.wikiPageReviewId,
                wikiPageId: pageId, wikiSpaceId: info.wikiSpaceId, pagePath: pagePathText, pageName: pageName, versionName: versionName,
                baseVersionName: info.publishedVersionName || null, authorUserId: me, authorName: authorName, note: note || null,
                dueDate: dueDate ? String(dueDate) : null}).userIds(recipients)
                .record('moqui.resource.wiki.WikiPageReview', review.wikiPageReviewId).reason('approval')
            if (link) nm.link(link)
            nm.send()
            const sentId = nm.getNotificationMessageId()
            if (sentId) {
                review.notificationMessageId = sentId
                review.update()
            }
        } catch (e) {
            ec.logger.error(`Review ${review.wikiPageReviewId} of ${info.wikiSpaceId}/${pagePathText} asked, but its notification was not sent: ${e}`)
        }
    }
    for (const open of replaced) {
        open.statusId = 'WprCancelled'
        open.decidedByUserId = me
        open.decidedDate = now
        open.decisionNote = 'Replaced by a newer request'
        open.update()
        if (open.notificationMessageId) ec.service.sync().name('org.moqui.impl.WikiServices.close#WikiPageReviewNotification')
                .parameter('notificationMessageId', open.notificationMessageId).call()
    }
}
wikiPageReviewId = wikiPageReviewIdList[0] || null

statusId = null
publishedVersionName = null
const me = ec.user.userId
const review = ec.entity.find('moqui.resource.wiki.WikiPageReview').condition('wikiPageReviewId', wikiPageReviewId).one()
const access = review ? ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageAccess').parameter('wikiPageId', review.wikiPageId).call() : null
if (review == null || !access.canView) { ec.message.addError(ec.l10n.localize('Review not found')); return }
const approve = ['approve', 'approved', 'WprApproved'].includes(decision)
const changes = ['changes', 'requestChanges', 'refuse', 'WprChangesRequested'].includes(decision)
if (!approve && !changes) { ec.message.addError(ec.resource.expand('A review is approved or sent back for changes, not ${decision}', '', {decision: String(decision)})); return }
if (review.statusId !== 'WprRequested') {
    const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', review.statusId).useCache(true).one()
    ec.message.addError(ec.resource.expand('This review is ${status} already', '', {status: ec.l10n.localize(status?.description || review.statusId || '').toLowerCase()}))
    return
}
const mayDecide = access.canAdmin || (review.reviewerUserId ? review.reviewerUserId === me :
        (access.canUpdate && review.requestedByUserId !== me))
if (!me || !mayDecide) { ec.message.addError(ec.l10n.localize('This review is not yours to decide')); return }
const noteText = decisionNote ? String(decisionNote).trim() : ''
if (changes && !noteText) { ec.message.addError(ec.l10n.localize('Say what to change')); return }
review.statusId = approve ? 'WprApproved' : 'WprChangesRequested'
review.decidedByUserId = me
review.decidedDate = ec.user.nowTimestamp
review.decisionNote = noteText || null
review.update()
statusId = review.statusId
if (approve && publish && review.versionName) {
    // the review's own publish: a named reviewer may decide without being able to update the page, so not
    // set#PublishedVersion, which asks for update
    ec.service.sync().name('update#moqui.resource.wiki.WikiPage')
            .parameters({wikiPageId: review.wikiPageId, publishedVersionName: review.versionName}).call()
    publishedVersionName = review.versionName
}
// the requester's notification opens what the request's did (its link), unless the caller gives one
let decisionLink = link || null
if (!decisionLink && review.notificationMessageId) {
    try {
        decisionLink = ec.entity.find('moqui.security.user.NotificationMessage')
                .condition('notificationMessageId', review.notificationMessageId).disableAuthz().one()?.linkText || null
    } catch (e) {
        ec.logger.warn(`The link of review ${wikiPageReviewId}'s request was not read: ${e}`)
    }
}
// the requester is told, then the reviewers' notification is marked decided
if (review.requestedByUserId && review.requestedByUserId !== me) {
