        const space = page ? ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', page.wikiSpaceId).useCache(true).one() : null
        const path = page?.pagePath || ''
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', me).useCache(true).disableAuthz().one()
        const nm = ec.makeNotificationMessage().topic('WikiPageReviewDecision').message({wikiPageReviewId: wikiPageReviewId,
            wikiPageId: review.wikiPageId, wikiSpaceId: page?.wikiSpaceId, pagePath: path,
            pageName: path ? path.slice(path.lastIndexOf('/') + 1) : (space?.description || page?.wikiSpaceId),
            versionName: review.versionName, reviewerUserId: me, reviewerName: account ? (account.userFullName || account.username) : me,
            decision: approve ? 'approved' : 'changes', decisionText: approve ? 'approved' : 'asked for changes to',
            decisionNote: noteText || null}).userId(review.requestedByUserId)
            .record('moqui.resource.wiki.WikiPageReview', wikiPageReviewId).reason('approval')
        if (decisionLink) nm.link(decisionLink)
        nm.send()
    } catch (e) {
        ec.logger.error(`The decision on review ${wikiPageReviewId} was made, but its notification was not sent: ${e}`)
    }
}
if (review.notificationMessageId) ec.service.sync().name('org.moqui.impl.WikiServices.close#WikiPageReviewNotification')
        .parameter('notificationMessageId', review.notificationMessageId).call()

const me = ec.user.userId
const review = ec.entity.find('moqui.resource.wiki.WikiPageReview').condition('wikiPageReviewId', wikiPageReviewId).one()
const access = review ? ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageAccess').parameter('wikiPageId', review.wikiPageId).call() : null
if (review == null || !access.canView) { ec.message.addError(ec.l10n.localize('Review not found')); return }
if (!me || (review.requestedByUserId !== me && !access.canAdmin)) { ec.message.addError(ec.l10n.localize('Only the one who asked for a review cancels it')); return }
