reviewList = []
reviewCount = 0
const me = ec.user.userId
if (!me) return
const scope = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiViewScope').call()
const viewSpaces = new Set(Array.from(scope.viewSpaceIdList || []))
const hidden = new Set(Array.from(scope.hiddenPageIdList || []))
const cf = ec.entity.conditionFactory
let find = ec.entity.find('moqui.resource.wiki.WikiPageReview').orderBy('-requestedDate,-wikiPageReviewId')
if (statusId && statusId !== 'any') find = find.condition('statusId', statusId)
if (wikiPageId) find = find.condition('wikiPageId', wikiPageId)
const scoped = !!(wikiSpaceId || wikiPageId)
if (filter === 'requested') find = find.condition('requestedByUserId', me)
else if (filter === 'toDo') find = find.condition(cf.makeCondition([cf.makeCondition('reviewerUserId', 'equals', me),
        cf.makeCondition('reviewerUserId', 'equals', null)], 'or'))
else if (!scoped) find = find.condition(cf.makeCondition([cf.makeCondition('reviewerUserId', 'equals', me),
        cf.makeCondition('reviewerUserId', 'equals', null), cf.makeCondition('requestedByUserId', 'equals', me)], 'or'))
const pages = new Map()
const pageOf = (id) => {
    if (!pages.has(id)) pages.set(id, ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', id).one())
    return pages.get(id)
}
const accesses = new Map()
const accessOf = (id) => {
    if (!accesses.has(id)) accesses.set(id, ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiPageAccess').parameter('wikiPageId', id).call())
    return accesses.get(id)
}
const users = {}
const userName = (userId) => {
