    const open = review.statusId === 'WprRequested'
    const isMine = review.reviewerUserId === me
    const forAnyone = !review.reviewerUserId
    const access = forAnyone || open ? accessOf(page.wikiPageId) : null
    if (filter === 'toDo' && forAnyone && (review.requestedByUserId === me || !access.canUpdate)) continue
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', page.wikiSpaceId).useCache(true).one()
    const path = page.pagePath || ''
    const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', review.statusId).useCache(true).one()
    reviewList.push({wikiPageReviewId: review.wikiPageReviewId, wikiPageId: page.wikiPageId, wikiSpaceId: page.wikiSpaceId,
        spaceDescription: space?.description || page.wikiSpaceId, pagePath: path,
        pageName: path ? path.slice(path.lastIndexOf('/') + 1) : (space?.description || page.wikiSpaceId),
        versionName: review.versionName, shortVersionName: short(review.versionName), baseVersionName: review.baseVersionName,
        publishedVersionName: page.publishedVersionName, statusId: review.statusId, statusDescription: status?.description || review.statusId,
        requestedByUserId: review.requestedByUserId, requestedByName: userName(review.requestedByUserId),
        reviewerUserId: review.reviewerUserId, reviewerName: userName(review.reviewerUserId), requestedDate: review.requestedDate,
