if (limit && reviewList.length > limit) reviewList = reviewList.slice(0, limit)

pageList = []
usedIndex = false
const needle = String(text || '').trim()
if (!needle) return
const scope = ec.service.sync().name('org.moqui.impl.WikiServices.get#WikiViewScope').call()
let spaceIds = Array.from(scope.viewSpaceIdList || [])
if (wikiSpaceId) spaceIds = spaceIds.filter((id) => id === wikiSpaceId)
if (!spaceIds.length) return
const hidden = Array.from(scope.hiddenPageIdList || [])
const hiddenSet = new Set(hidden)
const spaces = new Map()
const spaceOf = (id) => {
    if (!spaces.has(id)) spaces.set(id, ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', id).useCache(true).one())
    return spaces.get(id)
}
const nameOf = (spaceId, path) => path ? path.slice(path.lastIndexOf('/') + 1) : (spaceOf(spaceId)?.description || spaceId)
const rowOf = (body) => ({wikiPageId: body.wikiPageId, wikiSpaceId: body.wikiSpaceId, spaceDescription: spaceOf(body.wikiSpaceId)?.description || body.wikiSpaceId,
    pagePath: body.pagePath || '', pageName: body.pageName || nameOf(body.wikiSpaceId, body.pagePath || ''),
    title: body.title || nameOf(body.wikiSpaceId, body.pagePath || ''), updatedDate: body.updatedDate ?? null,
    updatedByUserId: body.updatedByUserId ?? null})
let documentTypes = []
try {
    if (ec.search.isAvailable()) documentTypes = Array.from(ec.entity.find('moqui.entity.document.DataDocument')
            .condition('primaryEntityName', 'moqui.resource.wiki.WikiPage').useCache(true).disableAuthz().list())
            .map((document) => document.dataDocumentId).filter((id) => ec.search.indexExists({documentType: id}))
} catch (e) {
    documentTypes = []
}
if (documentTypes.length) {
    try {
        const all = [{field: {name: 'wikiSpaceId', op: 'in', values: spaceIds}}, {text: {terms: needle, match: 'prefix'}}]
        if (hidden.length) all.push({field: {name: 'wikiPageId', op: 'in', values: hidden, negate: true}})
        const seen = new Set()
        for (const documentType of documentTypes) {
            const found = ec.search.search({documentType: documentType, query: {bool: {all: all}}, limit: limit})
            for (const hit of found.hits || []) {
                const body = hit.body || {}
                if (!body.wikiPageId || seen.has(body.wikiPageId) || hiddenSet.has(body.wikiPageId) || !spaceIds.includes(body.wikiSpaceId)) continue
                seen.add(body.wikiPageId)
                pageList.push(rowOf(body))
            }
        }
        usedIndex = true
        if (pageList.length > limit) pageList = pageList.slice(0, limit)
        return
    } catch (e) {
        ec.logger.warn(`Wiki page search fell back to the page paths: ${e}`)
    }
}
const lower = needle.toLowerCase()
const rows = Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', 'in', spaceIds)
        .orderBy('wikiSpaceId,pagePath').limit(10000).list())
for (const row of rows) {
    if (hiddenSet.has(row.wikiPageId) || !String(row.pagePath || '').toLowerCase().includes(lower)) continue
    pageList.push(rowOf({wikiPageId: row.wikiPageId, wikiSpaceId: row.wikiSpaceId, pagePath: row.pagePath || ''}))
    if (pageList.length >= limit) break
}

// a space is joined to every WikiSpaceUser row it has: keep it once, with the user's own row when there is one
const userFields = ['userId', 'receiveNotifications', 'allowAdmin', 'allowView', 'allowUpdate']
const own = (row) => userId != null && userId !== '' && row.userId === userId
const bySpace = new Map()
for (const row of wikiSpaceRowList) {
    const map = Object.assign({}, row.getMap ? row.getMap() : row)
    const mine = own(map)
    if (!mine) for (const name of userFields) map[name] = null
    const prior = bySpace.get(map.wikiSpaceId)
    if (!prior || (mine && !own(prior))) bySpace.set(map.wikiSpaceId, map)
}
wikiSpaceAndUserList = Array.from(bySpace.values())
const spaceIds = wikiSpaceAndUserList.map((space) => space.wikiSpaceId)
const pages = new Map()
if (spaceIds.length) {
    const cf = ec.entity.conditionFactory
    const viewable = cf.makeCondition([cf.makeCondition('restrictView', 'equals', 'N'), cf.makeCondition('restrictView', 'equals', null),
        cf.makeCondition([cf.makeCondition('userId', 'equals', userId || null), cf.makeCondition('restrictView', 'equals', 'Y'),
            cf.makeCondition('allowView', 'equals', 'Y')], 'and')], 'or')
    const pageRows = ec.entity.find('moqui.resource.wiki.WikiPageAndUser').condition('wikiSpaceId', 'in', spaceIds)
        .condition(viewable).selectField('wikiSpaceId').selectField('wikiPageId').list()
    for (const page of pageRows) {
        if (!pages.has(page.wikiSpaceId)) pages.set(page.wikiSpaceId, new Set())
        pages.get(page.wikiSpaceId).add(page.wikiPageId)
    }
}
for (const space of wikiSpaceAndUserList) space.pageCount = pages.has(space.wikiSpaceId) ? pages.get(space.wikiSpaceId).size : 0

resultList = []
for (const wikiPageAndUser of wikiPageAndUserList)
    resultList.push({wikiPageId:wikiPageAndUser.wikiPageId, pageLabel:`${wikiPageAndUser.wikiSpaceId}/${wikiPageAndUser.pagePath}`})
